COMMAND_PAGE = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Meme Sniper V0.7.3 - Command Centre</title><style>
:root{--bg:#11141a;--p:#1b1f27;--line:#303642;--txt:#eef1f5;--mut:#8f97a5;--g:#38d996;--r:#ff6570;--b:#55b8ff;--o:#ff9f1a}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--txt);font-family:Segoe UI,Arial,sans-serif}.w{max-width:1800px;margin:auto;padding:18px}.top,.row{display:flex;gap:10px;align-items:center;justify-content:space-between}.nav{display:flex;gap:7px}.btn{color:#dce2e9;text-decoration:none;border:1px solid #39414d;background:#222833;padding:8px 11px;border-radius:7px;font-size:12px}.sub,.mut{color:var(--mut);font-size:12px}.cards{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin:15px 0}.card,.panel{background:var(--p);border:1px solid var(--line);border-radius:9px}.card{padding:13px}.big{font-size:22px;font-weight:750;margin-top:5px}.grid{display:grid;grid-template-columns:1.25fr .75fr;gap:12px}.panel{padding:13px;margin-bottom:12px;overflow:auto}h1{margin:0;font-size:27px}h3{margin:0 0 10px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:8px;border-top:1px solid #2b303a;text-align:right;white-space:nowrap}th{color:#a9b0bc}th:first-child,td:first-child{text-align:left}.feed{display:flex;flex-direction:column;gap:7px}.event{border-left:3px solid #4a5362;background:#171b22;padding:9px 10px;border-radius:5px}.event.CLUSTER{border-left-color:var(--o)}.event.SMART_MONEY{border-left-color:var(--g)}.event.PAPER_COPY{border-left-color:var(--b)}.tag{font-size:10px;color:var(--mut);margin-bottom:3px}.title{font-weight:650}.detail{font-size:11px;color:var(--mut);margin-top:3px}.good{color:var(--g)}.bad{color:var(--r)}.score{font-weight:800;color:var(--o)}@media(max-width:1100px){.cards{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.w{padding:8px}}
</style></head><body><div class="w"><div class="top"><div><h1>Meme Sniper V0.7.3 - Command Centre</h1><div class="sub">Trader-first intelligence + verified V0.6 execution. PAPER ONLY.</div></div><div class="nav"><a class="btn" href="/">Dashboard</a><a class="btn" href="/tokens">Coins</a><a class="btn" href="/traders">Top Traders</a><a class="btn" href="/integrations">Integrations</a></div></div><div id="cards" class="cards"></div><div class="grid"><div><div class="panel"><h3>Live intelligence feed</h3><div id="feed" class="feed"></div></div></div><div><div class="panel"><h3>Best opportunities now</h3><table><thead><tr><th>Coin</th><th>Combined</th><th>Signal</th><th>Cluster</th><th>Wallets</th></tr></thead><tbody id="opp"></tbody></table></div><div class="panel"><h3>Smart-money clusters</h3><table><thead><tr><th>Coin</th><th>Wallets</th><th>Score</th><th>Value</th></tr></thead><tbody id="clusters"></tbody></table></div></div></div><div class="panel"><div class="row"><h3>Top trader intelligence</h3><a class="btn" href="/traders">Full leaderboard</a></div><table><thead><tr><th>Trader</th><th>Score</th><th>Tier</th><th>Sources</th><th>Nansen 24h</th><th>Copy</th><th>Our P/L</th><th>Tracked</th></tr></thead><tbody id="traders"></tbody></table></div></div><script>
const short=x=>x?x.slice(0,6)+'…'+x.slice(-5):'—';const money=x=>x==null?'—':'$'+Number(x).toLocaleString(undefined,{maximumFractionDigits:0});const ago=x=>{if(!x)return '';let s=(Date.now()-new Date(x))/1000;if(s<60)return Math.max(0,Math.round(s))+'s ago';if(s<3600)return Math.round(s/60)+'m ago';return Math.round(s/3600)+'h ago'};async function load(){try{const [st,tr,cl,op,fd]=await Promise.all([fetch('/api/v07/status').then(r=>r.json()),fetch('/api/v07/traders?limit=12').then(r=>r.json()),fetch('/api/v07/clusters?limit=10').then(r=>r.json()),fetch('/api/v07/opportunities?limit=12').then(r=>r.json()),fetch('/api/v07/live-feed?limit=60').then(r=>r.json())]);let ns=st.nansen_enabled?(st.nansen_configured?'ACTIVE':'NO KEY'):'OFF';document.getElementById('cards').innerHTML=[['Nansen',ns],['Trader universe',st.trader_universe+'/'+st.universe_cap],['Live tracked',st.live_tracked],['Clusters',st.clusters_total],['Nansen new',st.nansen_last_new_trades],['Credits',st.nansen_credits_remaining??'—']].map(x=>`<div class="card"><div class="mut">${x[0]}</div><div class="big">${x[1]}</div></div>`).join('');document.getElementById('feed').innerHTML=fd.map(x=>`<div class="event ${x.type}"><div class="tag">${x.source} · ${x.type} · ${ago(x.ts)}</div><div class="title">${x.title}</div><div class="detail">${x.detail||''}</div></div>`).join('')||'<div class="mut">Waiting for live intelligence…</div>';document.getElementById('opp').innerHTML=op.map(x=>`<tr><td>${x.symbol||short(x.mint)}</td><td class="score">${x.score}</td><td>${x.signal_score??'—'}</td><td>${x.cluster_score??'—'}</td><td>${x.cluster_wallets}</td></tr>`).join('');document.getElementById('clusters').innerHTML=cl.map(x=>`<tr><td>${x.symbol||short(x.token_mint)}</td><td>${x.wallets}</td><td class="score">${x.score}</td><td>${money(x.value_usd)}</td></tr>`).join('');document.getElementById('traders').innerHTML=tr.map(x=>`<tr><td>${x.label||short(x.wallet)}</td><td class="score">${x.score}</td><td>${x.tier}</td><td>${x.sources.join('+')}</td><td>${x.nansen_trades_24h}</td><td>${x.copy_score??'—'} (${x.copy_obs})</td><td class="${x.paper_pnl>=0?'good':'bad'}">${Number(x.paper_pnl)>=0?'+':''}$${Number(x.paper_pnl).toFixed(2)}</td><td>${x.tracked?'YES':'NO'}</td></tr>`).join('');}catch(e){console.error(e)}}load();setInterval(load,5000);</script></body></html>'''

TRADERS_PAGE = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Meme Sniper V0.7.3 - Top Traders</title><style>body{margin:0;background:#12151b;color:#eef1f5;font-family:Segoe UI,Arial,sans-serif}.w{max-width:1750px;margin:auto;padding:18px}.top{display:flex;justify-content:space-between;align-items:center}.nav{display:flex;gap:7px}.btn{color:#dce2e9;text-decoration:none;border:1px solid #39414d;background:#222833;padding:8px 11px;border-radius:7px;font-size:12px}.panel{background:#1b1f27;border:1px solid #303642;border-radius:9px;margin-top:15px;overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:10px;border-top:1px solid #2b303a;text-align:right;white-space:nowrap}th{background:#343a44;color:#c6ccd5;position:sticky;top:0}th:first-child,td:first-child{text-align:left}.score{color:#ff9f1a;font-weight:800}.good{color:#38d996}.bad{color:#ff6570}.mut{color:#929aa8;font-size:12px}h1{margin:0}</style></head><body><div class="w"><div class="top"><div><h1>Meme Sniper V0.7.3 - Trader Intelligence</h1><div class="mut">Historical quality + Nansen activity + verified copyability + our actual paper-copy results.</div></div><div class="nav"><a class="btn" href="/command">Command Centre</a><a class="btn" href="/tokens">Coins</a><a class="btn" href="/">Dashboard</a><a class="btn" href="/integrations">Integrations</a></div></div><div class="panel"><table><thead><tr><th>TRADER</th><th>SCORE</th><th>TIER</th><th>SOURCES</th><th>HIST</th><th>NANSEN 24H</th><th>24H VALUE</th><th>TOKENS</th><th>COPY SCORE</th><th>OBS</th><th>OUR TRADES</th><th>WIN</th><th>OUR P/L</th><th>TRACKED</th></tr></thead><tbody id="rows"></tbody></table></div></div><script>const short=x=>x?x.slice(0,7)+'…'+x.slice(-6):'—';const money=x=>'$'+Number(x||0).toLocaleString(undefined,{maximumFractionDigits:0});async function load(){let d=await fetch('/api/v07/traders?limit=500').then(r=>r.json());document.getElementById('rows').innerHTML=d.map((x,i)=>`<tr><td>#${i+1} ${x.label||short(x.wallet)}<div class="mut">${short(x.wallet)}</div></td><td class="score">${x.score}</td><td>${x.tier}</td><td>${x.sources.join('+')}</td><td>${x.historical}</td><td>${x.nansen_trades_24h}</td><td>${money(x.nansen_volume_24h)}</td><td>${x.distinct_tokens}</td><td>${x.copy_score??'—'}</td><td>${x.copy_obs}</td><td>${x.paper_trades}</td><td>${x.paper_win==null?'—':x.paper_win+'%'}</td><td class="${x.paper_pnl>=0?'good':'bad'}">${x.paper_pnl>=0?'+':''}$${Number(x.paper_pnl).toFixed(2)}</td><td>${x.tracked?'YES':'NO'}</td></tr>`).join('')}load();setInterval(load,10000);</script></body></html>'''


INTEGRATIONS_PAGE = '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Meme Sniper V0.7.3 - Integrations</title><style>\n:root{--bg:#11141a;--p:#1b1f27;--line:#303642;--txt:#eef1f5;--mut:#8f97a5;--g:#38d996;--r:#ff6570;--y:#ffd166}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--txt);font-family:Segoe UI,Arial,sans-serif}.w{max-width:1650px;margin:auto;padding:18px}\n.top{display:flex;justify-content:space-between;align-items:center;gap:12px}.nav{display:flex;gap:7px;flex-wrap:wrap}.btn{color:#dce2e9;text-decoration:none;border:1px solid #39414d;background:#222833;padding:8px 11px;border-radius:7px;font-size:12px}\nh1{margin:0;font-size:27px}.sub,.mut{color:var(--mut);font-size:12px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:15px 0}.card,.module{background:var(--p);border:1px solid var(--line);border-radius:10px}.card{padding:13px}.big{font-size:23px;font-weight:760;margin-top:5px}\n.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.module{padding:14px}.head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.name{font-size:18px;font-weight:750}.kind{color:var(--mut);font-size:10px;margin-top:3px}.purpose{font-size:12px;color:#bac1cb;line-height:1.45;margin:12px 0}\n.badge{font-size:11px;font-weight:800;padding:5px 8px;border-radius:999px;border:1px solid}.ACTIVE{color:var(--g);border-color:#245f4a;background:#153729}.SHADOW{color:#55b8ff;border-color:#285b80;background:#14293a}.OFF{color:#9ca3af;border-color:#464b55;background:#292d34}.WARNING,.NEEDSKEY{color:var(--y);border-color:#6f602e;background:#3d3517}.LOCKED{color:#ff8b93;border-color:#6c3338;background:#3a1d20}\n.metrics{display:grid;grid-template-columns:1fr 1fr;gap:7px}.metric{background:#171b22;border:1px solid #292f39;border-radius:6px;padding:8px}.mlabel{font-size:10px;color:var(--mut)}.mvalue{font-weight:700;margin-top:3px;overflow-wrap:anywhere}.added{font-size:10px;color:#78818f;margin-top:10px}.warning{font-size:11px;color:var(--y);background:#302b18;border:1px solid #5a4e24;padding:7px;border-radius:6px;margin-top:8px;overflow-wrap:anywhere}\n.legend{background:#171b22;border:1px solid #292f39;border-radius:8px;padding:10px 12px;margin-bottom:12px;font-size:12px;color:#aeb5bf;line-height:1.5}\n@media(max-width:1000px){.grid{grid-template-columns:1fr}.cards{grid-template-columns:repeat(2,1fr)}.w{padding:8px}}@media(max-width:600px){.cards{grid-template-columns:1fr}}\n</style></head><body><div class="w"><div class="top"><div><h1>Meme Sniper V0.7.3 - Integrations & Modules</h1><div class="sub">What is connected, what it does, and whether it is healthy. API secrets are never displayed.</div></div>\n<div class="nav"><a class="btn" href="/">Dashboard</a><a class="btn" href="/command">Command Centre</a><a class="btn" href="/tokens">Coins</a><a class="btn" href="/traders">Top Traders</a><a class="btn" href="/integrations">Integrations</a></div></div>\n<div id="cards" class="cards"></div><div class="legend"><b>Status:</b> ACTIVE = enabled/configured · SHADOW = simulated research only, excluded from verified P/L · NEEDS KEY = switched on but missing credentials · WARNING = provider reported an error · OFF = intentionally disabled · LOCKED = safety restriction.</div><div id="modules" class="grid"></div></div>\n<script>\nconst esc=s=>String(s??\'\').replace(/[&<>"\']/g,m=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#039;\'}[m]));\nconst cls=s=>String(s||\'OFF\').replace(/\\s/g,\'\');\nasync function load(){try{const d=await fetch(\'/api/integrations\').then(r=>{if(!r.ok)throw new Error(\'HTTP \'+r.status);return r.json()});\ndocument.getElementById(\'cards\').innerHTML=[[\'Version\',d.version],[\'Active modules\',d.active],[\'Warnings / setup\',d.warning],[\'Disabled\',d.off]].map(x=>`<div class="card"><div class="mut">${x[0]}</div><div class="big">${x[1]}</div></div>`).join(\'\');\ndocument.getElementById(\'modules\').innerHTML=d.modules.map(x=>`<div class="module"><div class="head"><div><div class="name">${esc(x.name)}</div><div class="kind">${esc(x.kind)}</div></div><span class="badge ${cls(x.state)}">${esc(x.state)}</span></div><div class="purpose">${esc(x.purpose)}</div><div class="metrics">${(x.metrics||[]).map(m=>`<div class="metric"><div class="mlabel">${esc(m[0])}</div><div class="mvalue">${esc(m[1])}</div></div>`).join(\'\')}</div>${x.warning?`<div class="warning">${esc(x.warning)}</div>`:\'\'}<div class="added">Added / upgraded: ${esc(x.added)}</div></div>`).join(\'\');\n}catch(e){document.getElementById(\'modules\').innerHTML=`<div class="warning">Status failed: ${esc(e.message)}</div>`}}\nload();setInterval(load,10000);\n</script></body></html>'
